// Property 2: Column model of the TLE fields (design.md, Correctness Properties).
//
// For any TLE generated by formatting random field values into the C18 columns (NORAD 1-99999
// zero-padded, international designator, epoch year 00-99, epoch day, inclination, RAAN, eccentricity
// digits, argument of perigee, mean anomaly, mean motion > 0), `parseTle` either rejects it with
// `invalid-tle` exactly when satellite.js `twoline2satrec` reports a non-zero error code or `propagate`
// at the model EPOCH returns no finite state, or returns a frozen record whose fields equal the model
// exactly: `NORAD_CAT_ID = Number(noradText)`, `OBJECT_ID` = trimmed designator,
// `EPOCH = Date.UTC(year, 0, 0) + Number(dayText) × 86 400 000` with the C02 century rule,
// `INCLINATION`, `RA_OF_ASC_NODE`, `ARG_OF_PERICENTER`, `MEAN_ANOMALY`, `MEAN_MOTION` equal to
// `Number(trimmed text)`, `ECCENTRICITY = Number('0.' + digits)`, `SEMIMAJOR_AXIS_KM` and
// `ALTITUDE_KM` within 10⁻⁹ km of formula 2.9.7 and C19, and every instant field of type `number`.
import fc from 'fast-check';
import { propagate, twoline2satrec } from 'satellite.js';
import { expect, it } from 'vitest';
import { EngineError, parseTle } from '../../src/lib/orbit/index';
import { formatTle, tleFieldsArb, type TleFields } from '../helpers/arbitraries';

// "Property test settings" of design.md (D20, D21): Property 2 runs 200 cases, and every case runs
// `twoline2satrec`, so the test gets a timeout of 20 000 ms.
const NUM_RUNS = 200;
const TIMEOUT_MS = 20_000;

// Constants of formula 2.9.7 and C19, written out here so that the model shares nothing with the parser.
const MU_KM3_PER_S2 = 398600.4418;
const WGS84_A_KM = 6378.137;
const MS_PER_DAY = 86_400_000;
const SECONDS_PER_DAY = 86_400;

/** Tolerance of the semi-major axis and the altitude: 10⁻⁹ km. */
const AXIS_TOLERANCE_KM = 1e-9;

/** The record that the column model predicts for the generated field texts (Requirement 4, criteria 4 to 9 and 24). */
function modelOf(fields: TleFields) {
  // C02 century rule and formula 2.9.1.
  const yy = Number(fields.epochYearText);
  const year = yy < 57 ? 2000 + yy : 1900 + yy;

  // Formula 2.9.7 from the raw mean motion: n in rad/s, a = (mu / n^2)^(1/3), then h = a - 6378.137 (C19).
  const meanMotion = Number(fields.meanMotionText.trim());
  const n = (meanMotion * 2 * Math.PI) / SECONDS_PER_DAY;
  const semiMajorAxisKm = (MU_KM3_PER_S2 / (n * n)) ** (1 / 3);

  return {
    exact: {
      NORAD_CAT_ID: Number(fields.noradText),
      OBJECT_ID: fields.designator.trim(),
      EPOCH: Date.UTC(year, 0, 0) + Number(fields.epochDayText) * MS_PER_DAY,
      INCLINATION: Number(fields.inclinationText.trim()),
      RA_OF_ASC_NODE: Number(fields.raanText.trim()),
      ARG_OF_PERICENTER: Number(fields.argOfPerigeeText.trim()),
      MEAN_ANOMALY: Number(fields.meanAnomalyText.trim()),
      MEAN_MOTION: meanMotion,
      ECCENTRICITY: Number(`0.${fields.eccentricityDigits}`),
    },
    semiMajorAxisKm,
    altitudeKm: semiMajorAxisKm - WGS84_A_KM,
  };
}

/**
 * The accept-or-reject decision of satellite.js 6.0.2 for the two lines: `twoline2satrec` reports error
 * code 0, and `propagate` at the model EPOCH returns a position and a velocity with finite components.
 */
function satelliteJsAccepts(line1: string, line2: string, epochMs: number): boolean {
  const satrec = twoline2satrec(line1, line2);
  if (satrec.error !== 0) {
    return false;
  }
  const state = propagate(satrec, new Date(epochMs));
  // satellite.js 6.0.2 returns null when propagation fails, although its declaration says otherwise.
  if (state === null) {
    return false;
  }
  const { position, velocity } = state;
  return [position.x, position.y, position.z, velocity.x, velocity.y, velocity.z].every(Number.isFinite);
}

/** Calls `parseTle` on a text that it must reject and returns the Engine_Error that it reports. */
function rejection(text: string): EngineError {
  try {
    parseTle(text);
  } catch (error) {
    if (error instanceof EngineError) {
      return error;
    }
    throw error;
  }
  throw new Error('parseTle accepted a TLE that satellite.js rejects');
}

// Feature: orbit-engine, Property 2: Column model of the TLE fields
// **Validates: Requirements 2.8, 4.4, 4.5, 4.6, 4.7, 4.8, 4.9, 4.24, 5.11**
it(
  'Property 2: Column model of the TLE fields',
  () => {
    fc.assert(
      fc.property(tleFieldsArb, (fields) => {
        const { name, line1, line2 } = formatTle(fields);
        const text = `${name}\n${line1}\n${line2}`;
        const model = modelOf(fields);

        if (!satelliteJsAccepts(line1, line2, model.exact.EPOCH)) {
          expect(rejection(text).category).toBe('invalid-tle');
          return;
        }

        const record = parseTle(text);
        expect(Object.isFrozen(record)).toBe(true);
        expect({
          NORAD_CAT_ID: record.NORAD_CAT_ID,
          OBJECT_ID: record.OBJECT_ID,
          EPOCH: record.EPOCH,
          INCLINATION: record.INCLINATION,
          RA_OF_ASC_NODE: record.RA_OF_ASC_NODE,
          ARG_OF_PERICENTER: record.ARG_OF_PERICENTER,
          MEAN_ANOMALY: record.MEAN_ANOMALY,
          MEAN_MOTION: record.MEAN_MOTION,
          ECCENTRICITY: record.ECCENTRICITY,
        }).toStrictEqual(model.exact);
        expect(Math.abs(record.SEMIMAJOR_AXIS_KM - model.semiMajorAxisKm)).toBeLessThanOrEqual(AXIS_TOLERANCE_KM);
        expect(Math.abs(record.ALTITUDE_KM - model.altitudeKm)).toBeLessThanOrEqual(AXIS_TOLERANCE_KM);
        expect(typeof record.EPOCH).toBe('number');
      }),
      { numRuns: NUM_RUNS },
    );
  },
  TIMEOUT_MS,
);
